package com.almus.appcreatorpro.debug

/**
 * Phase 22: human-written knowledge for the diagnosis layer. Nothing here is generated by an AI model, and nothing is
 * guessed: every explanation is general knowledge about WHY that kind of error exists. It never states a cause that
 * only the project could confirm; where several causes are possible the text lists them as possibilities.
 */
internal object ErrorExplanations {

    /** Why errors of this analyzer rule happen, or null when there is no built-in explanation for the rule. */
    fun why(issue: BuildIssue): String? {
        val symbol = issue.symbol?.takeIf { it.isNotBlank() }
        val fixed = WHY[issue.rule]
        if (fixed != null) return fixed(symbol)
        return null
    }

    private val WHY: Map<String, (String?) -> String> = mapOf(
        "kotlin.unresolved-reference" to { s ->
            "The compiler looked for ${s?.let { "`$it`" } ?: "this name"} in the current scope, the file's imports and the module's dependencies and found nothing. " +
                "Possible reasons: a typo, a missing import, a class from a library that is not in `dependencies`, or a generated class (R, BuildConfig, view binding) that was not generated. The log alone cannot tell which one applies."
        },
        "kotlin.type-mismatch" to { _ -> "Kotlin never converts between types implicitly. The expression has one type, but the variable, parameter or return type that receives it expects another." },
        "kotlin.val-reassign" to { _ -> "A `val` is read-only after its first assignment, so a second assignment is rejected at compile time." },
        "kotlin.nullable-receiver" to { _ -> "The value's type allows null. Kotlin only allows member access on it after a null check, or with a safe call (`?.`), so that a NullPointerException cannot happen unnoticed." },
        "kotlin.smart-cast" to { _ -> "A null/type check only narrows a value if the compiler can prove it cannot change before it is used. Mutable properties and properties from other modules cannot be proven stable." },
        "kotlin.missing-return" to { _ -> "A function with a declared return type must produce a value on every path that leaves it; the compiler found a path that ends without one." },
        "kotlin.missing-argument" to { s -> "The call does not supply ${s?.let { "`$it`" } ?: "a required parameter"} and the function declaration gives it no default value." },
        "kotlin.not-initialized" to { _ -> "A local variable or property is read on a path where it has not been assigned yet." },
        "kotlin.when-exhaustive" to { _ -> "A `when` used as an expression (or on a sealed/enum type) has to cover every possible value; some are missing and there is no `else`." },
        "kotlin.abstract-member" to { _ -> "A non-abstract class has to implement every abstract member it inherits; at least one is still missing." },
        "kotlin.redeclaration" to { _ -> "Two declarations with the same name and signature exist in the same scope or package, so the compiler cannot decide which one a use refers to." },
        "kotlin.private-access" to { _ -> "The member's visibility (private, protected or internal) does not allow access from this place." },
        "kotlin.composable-context" to { _ -> "Compose tracks state through the call stack, so a @Composable function may only be called from another @Composable function (or a composition entry such as `setContent`)." },
        "kotlin.overload" to { _ -> "More than one function fits the call, or none fits and the compiler cannot infer a type argument from the arguments given." },
        "kotlin.binary-incompatible" to { _ -> "A library on the class path was compiled by a Kotlin compiler newer than the one building this project, so this compiler cannot read its metadata." },
        "kotlin.syntax" to { _ -> "The text at this place is not valid Kotlin grammar (for example a missing bracket, quote, comma or keyword). Parser errors are often reported one or more lines after the real mistake, and can cause follow-up errors." },
        "kotlin.unused" to { _ -> "The compiler found a declaration that is never used. This is a warning, not a build failure." },
        "kotlin.deprecated" to { _ -> "The API is marked `@Deprecated` by its authors, usually because a replacement exists. It still works today." },
        "kotlin.unchecked-cast" to { _ -> "Generic type arguments are erased at run time, so the cast cannot be verified and may fail later." },

        "java.cannot-find-symbol" to { s -> "javac could not find ${s?.let { "`$it`" } ?: "this symbol"} (a variable, method or class) in scope. Possible reasons: a typo, a missing import, a missing dependency, or a member that does not exist in that class." },
        "java.package-missing" to { s -> "The imported package ${s?.let { "`$it`" } ?: ""} is not on the compile class path: either the library that contains it is not in `dependencies`, or the name is misspelled." },
        "java.incompatible-types" to { _ -> "Java only allows assignment between compatible types, and it refuses conversions that could lose information (for example `double` to `int`) unless you cast explicitly." },
        "java.syntax" to { _ -> "The text is not valid Java grammar here. javac often reports the problem at the point where it gave up, which can be after the real mistake, and one syntax error can cause several follow-up errors." },
        "java.unreported-exception" to { _ -> "A checked exception must either be caught or declared with `throws`; this call can throw one that is neither." },
        "java.not-initialized" to { _ -> "Java requires a local variable to be assigned on every path before it is read." },
        "java.missing-return" to { _ -> "A method with a return type has a path that ends without a `return`." },
        "java.unreachable" to { _ -> "Code placed after a `return`, `throw`, `break` or an endless loop can never run, which javac treats as an error." },
        "java.final-assign" to { _ -> "A `final` variable can be assigned only once." },
        "java.already-defined" to { _ -> "Two variables or methods with the same name and signature exist in the same scope." },
        "java.public-class-file" to { _ -> "A public top-level class must live in a file with the same name as the class." },
        "java.override" to { _ -> "`@Override` was used, or an abstract method was left unimplemented, but no matching method exists in the supertype." },
        "java.static-context" to { _ -> "A static method cannot use instance members because there is no object to read them from." },
        "java.method-args" to { _ -> "No overload of the method or constructor accepts the arguments that were passed (count or types differ)." },
        "java.invalid-release" to { _ -> "The configured Java source/target/release version is not supported by the JDK that runs the build." },
        "java.deprecated" to { _ -> "The API is marked deprecated (or for removal) by its authors. It still compiles today." },
        "java.unchecked" to { _ -> "A generic operation cannot be checked at compile time because of type erasure." },

        "resource.not-found" to { s -> "AAPT2 resolves every `@type/name` reference when it links resources, and no resource ${s?.let { "`$it`" } ?: ""} exists in the app or in any library it uses." },
        "resource.attribute-not-found" to { s -> "The XML uses the attribute ${s?.let { "`$it`" } ?: ""} but no loaded theme/library defines it. Typical reasons: a typo, a missing `xmlns` declaration, or a library that provides the attribute is not a dependency." },
        "resource.duplicate" to { _ -> "Two resource files (possibly from different libraries or source sets) define a resource with the same type and name, and the merger cannot choose one." },
        "resource.xml-parse" to { _ -> "The XML file is not well-formed: AAPT2 uses a strict parser, and a single unclosed tag, quote or special character stops resource processing for the whole module." },
        "resource.incompatible-value" to { _ -> "The value written in the XML does not fit the type of the attribute (for example text where a dimension or colour is required)." },
        "resource.apostrophe" to { _ -> "In an Android string resource an apostrophe must be escaped (`\\'`) or the whole text quoted, because AAPT2 treats it as a quote character." },

        "manifest.exported" to { _ -> "Since Android 12 (targetSdk 31) every activity, service or receiver with an intent filter must say explicitly whether other apps may start it." },
        "manifest.merge-conflict" to { s -> "Your manifest and a library's manifest set different values for ${s?.let { "`$it`" } ?: "the same attribute"}, and the manifest merger needs a rule to decide which one wins." },
        "manifest.package-attr" to { _ -> "Current Android Gradle plugin versions take the app's namespace from the `namespace` property in the build file, not from the `package` attribute of the manifest." },
        "manifest.unexpected-element" to { _ -> "The manifest contains an element or attribute in a place where the manifest format does not allow it." },
        "manifest.activity-missing" to { _ -> "The manifest names a component class that the build could not find." },

        "sdk.location" to { _ -> "Gradle needs to know where the Android SDK is installed; neither `local.properties` (`sdk.dir`) nor the ANDROID_HOME / ANDROID_SDK_ROOT environment variables point to it on this machine." },
        "sdk.platform-missing" to { s -> "The project asks for Android platform ${s?.let { "`$it`" } ?: ""} (`compileSdk`) and it is not installed on the build machine." },
        "sdk.build-tools" to { s -> "The requested Android build-tools ${s?.let { "`$it`" } ?: "revision"} are not installed on the build machine." },
        "sdk.licenses" to { _ -> "Android SDK packages can only be installed automatically after their licence has been accepted on that machine." },
        "sdk.agp-java" to { s -> "This version of the Android Gradle plugin needs ${s?.let { "JDK $it" } ?: "a newer JDK"} to run, and the JDK that runs Gradle is older." },
        "sdk.class-version" to { _ -> "A class file was built for a newer Java version than the JVM that is trying to read it (the number in the message is the class file version)." },
        "sdk.compile-sdk-low" to { _ -> "A dependency is built against a newer Android API level than `compileSdk` of this project, and Gradle refuses to compile against an older one." },
        "sdk.min-sdk-lib" to { _ -> "A library needs a higher minimum Android version than the app declares as `minSdk`." },

        "dependency.not-found" to { s -> "Gradle searched every repository declared for this build and none of them offers ${s?.let { "`$it`" } ?: "the dependency"}. Possible reasons: a wrong group, name or version, the repository that hosts it is not declared, or the download itself failed (see the network entries if there are any)." },
        "dependency.failed-resolve" to { s -> "Android Gradle could not resolve ${s?.let { "`$it`" } ?: "the dependency"}: the coordinate does not exist in the configured repositories, or the repositories could not be reached." },
        "dependency.plugin-missing" to { _ -> "Gradle looks for a plugin in the repositories listed under `pluginManagement` in settings.gradle(.kts); the plugin id/version was not found in any of them." },
        "dependency.duplicate-class" to { s -> "Two libraries on the class path both contain ${s?.let { "`$it`" } ?: "the same class"}. Android builds cannot merge two copies, so the dexing step stops." },
        "dependency.no-variant" to { _ -> "Gradle picks a library variant by matching attributes (platform, build type, Java version). None of the variants the library publishes matches this app." },
        "dependency.network" to { _ -> "A request to a repository failed or was refused; see the Network entry for the specific kind of failure." },

        "gradle.min-version" to { _ -> "The Android Gradle plugin version declares the oldest Gradle it supports, and the Gradle that runs the build is older than that." },
        "gradle.method-missing" to { s -> "The build script calls ${s?.let { "`$it(...)`" } ?: "a function"} that Gradle does not know in this block. Either a plugin that provides it is not applied, or it is used in the wrong block." },
        "gradle.property-missing" to { s -> "The script reads ${s?.let { "`$it`" } ?: "a property"} which does not exist on this object, typically because the plugin that adds it is not applied or the name is misspelled." },
        "gradle.namespace" to { _ -> "Android Gradle plugin 8 requires every Android module to declare `namespace` in its `android { }` block." },
        "gradle.jvm-target" to { _ -> "Java and Kotlin compile tasks of the same module target different JVM versions, which Gradle checks before compiling." },
        "gradle.memory" to { _ -> "The JVM that runs Gradle or the Kotlin compiler ran out of memory (heap or metaspace) for the size of this build." },
        "gradle.dex-limit" to { _ -> "A single DEX file can reference at most 65,536 methods; the app has more than that and multidex is not enabled." },
        "gradle.wrapper-permission" to { _ -> "The `gradlew` script is not executable, or missing, on the machine that runs the build (a common result of committing it from Windows)." },
        "gradle.r8-missing" to { _ -> "R8 shrinks the app and found references to classes that are not available. Libraries often reference optional classes that are simply absent, and R8 needs a rule to accept that." },
        "gradle.lint" to { _ -> "Android lint found problems that are configured to stop the build (usually for release builds)." },
    )
}

/** What a stack trace's root-cause exception type tells, in general terms. */
internal data class ExceptionKnowledgeEntry(
    val category: DiagnosisCategory,
    val scope: FixScope,
    val why: String,
    val solution: String,
)

internal object ExceptionKnowledge {

    /** Knowledge for [simpleName] (for example `NoSuchMethodError`), or null when the type alone says too little. */
    fun forType(simpleName: String): ExceptionKnowledgeEntry? = TABLE[simpleName]

    private val BINARY = ExceptionKnowledgeEntry(
        DiagnosisCategory.DEPENDENCY_CONFLICT, FixScope.PROJECT_CONFIG,
        "Code was compiled against one version of a library and is running against another in which this member is missing or has a different shape. Usually two versions of the same library (or two libraries that need different versions) are on the class path.",
        "Find the library in the message and see which versions are on the class path (`./gradlew :app:dependencies` or `dependencyInsight --dependency <name>`). Align them: use one version for all, or a BOM/`constraints` block.",
    )

    private val TABLE: Map<String, ExceptionKnowledgeEntry> = mapOf(
        "OutOfMemoryError" to ExceptionKnowledgeEntry(
            DiagnosisCategory.GRADLE, FixScope.ENVIRONMENT,
            "The JVM ran out of memory (heap, metaspace or GC time). For a build this means the Gradle daemon or the Kotlin daemon has less memory than the project needs.",
            "Raise the limit in gradle.properties, for example `org.gradle.jvmargs=-Xmx4g -XX:MaxMetaspaceSize=1g` and, for Kotlin, `kotlin.daemon.jvmargs=-Xmx2g`. A GitHub-hosted runner has limited memory, so very large values may not help.",
        ),
        "StackOverflowError" to ExceptionKnowledgeEntry(
            DiagnosisCategory.JVM_EXCEPTION, FixScope.UNKNOWN,
            "The call stack became too deep: a method calls itself (directly or through others) without ending, or something is nested extremely deeply. Look at the repeating frames of the trace.",
            "Find the frames that repeat in the trace and check the condition that should stop the recursion.",
        ),
        "NullPointerException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.JVM_EXCEPTION, FixScope.PROJECT_CODE,
            "Code used a reference that was null. The top frame in your own code (if the trace has one) is where the null value was used; where it came from can be earlier.",
            "Open the first project frame, find which value is null on that line, and either make sure it is set before, or handle null (`?.`, `?:`, an `if` check).",
        ),
        "NoSuchMethodError" to BINARY,
        "NoSuchFieldError" to BINARY,
        "AbstractMethodError" to BINARY,
        "IncompatibleClassChangeError" to BINARY,
        "NoClassDefFoundError" to ExceptionKnowledgeEntry(
            DiagnosisCategory.DEPENDENCY_RESOLUTION, FixScope.PROJECT_CONFIG,
            "A class that was present when the code was compiled is not on the class path at run time. Possible reasons: a dependency that is only used at compile time, shrinking (R8/ProGuard) removed the class, or a plugin needs a class from a Gradle/AGP version that is not the one in use.",
            "Name the missing class from the message, then check that the library containing it is a runtime dependency (`implementation`, not `compileOnly`) and, for release builds, that no shrinker rule removes it.",
        ),
        "ClassNotFoundException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.DEPENDENCY_RESOLUTION, FixScope.PROJECT_CONFIG,
            "A class was looked up by name and is not on the class path. Possible reasons: a missing dependency, a misspelled class name in a string/manifest, or shrinking removed it.",
            "Check the class name in the message against your dependencies and the manifest, and for release builds against your R8/ProGuard rules.",
        ),
        "UnsupportedClassVersionError" to ExceptionKnowledgeEntry(
            DiagnosisCategory.ANDROID_SDK, FixScope.PROJECT_CONFIG,
            "A class file was built for a newer Java version than the JVM that is reading it.",
            "Run the build with a JDK at least as new as the one named in the message (in GitHub Actions set `java-version` in `actions/setup-java`).",
        ),
        "UnknownHostException" to network(),
        "SocketTimeoutException" to network(),
        "ConnectException" to network(),
        "SSLHandshakeException" to network(),
        "SSLException" to network(),
        "SocketException" to network(),
        "NoRouteToHostException" to network(),
        "ZipException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.DEPENDENCY_CONFLICT, FixScope.PROJECT_CONFIG,
            "An archive operation failed. For a build, \"duplicate entry\" usually means two libraries contain a file with the same path and packaging cannot merge them; otherwise the archive may be corrupted.",
            "If the message says \"duplicate entry\", exclude or pick one of the files in `packaging { resources { ... } }`. If the archive is corrupted, delete the Gradle cache for that library and build again.",
        ),
        "FileNotFoundException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.GRADLE, FixScope.PROJECT_CONFIG,
            "A file or folder that the build or program tried to open does not exist (the path is in the message).",
            "Check that the path in the message exists in the project or on the build machine, and that its name and case are exactly right (Linux paths are case sensitive).",
        ),
        "NoSuchFileException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.GRADLE, FixScope.PROJECT_CONFIG,
            "A file or folder that the build or program tried to open does not exist (the path is in the message).",
            "Check that the path in the message exists in the project or on the build machine, and that its name and case are exactly right (Linux paths are case sensitive).",
        ),
        "ClassCastException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.JVM_EXCEPTION, FixScope.PROJECT_CODE,
            "A value was cast to a type it does not have. The message names both types.",
            "Open the first project frame and check what value reaches the cast; use `is` / `as?` instead of an unconditional cast.",
        ),
        "IndexOutOfBoundsException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.JVM_EXCEPTION, FixScope.PROJECT_CODE,
            "An index was used that is outside the list, array or string. The message states the index and the size.",
            "Open the first project frame and check how the index is calculated and whether the collection can be empty.",
        ),
        "ArrayIndexOutOfBoundsException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.JVM_EXCEPTION, FixScope.PROJECT_CODE,
            "An index was used that is outside the array. The message states the index and the length.",
            "Open the first project frame and check how the index is calculated and whether the array can be empty.",
        ),
        "NumberFormatException" to ExceptionKnowledgeEntry(
            DiagnosisCategory.JVM_EXCEPTION, FixScope.PROJECT_CODE,
            "Text that is not a valid number was converted to a number; the message shows the text.",
            "Validate or trim the text before converting, or use `toIntOrNull()` and handle null.",
        ),
    )

    private fun network() = ExceptionKnowledgeEntry(
        DiagnosisCategory.NETWORK, FixScope.ENVIRONMENT,
        "A connection could not be made or was interrupted. This is usually about the network path or the server, not about your code.",
        "If the cause was temporary, run the build again. If it repeats, check the host named in the message and whether the build machine can reach it.",
    )
}

enum class NetworkKind(val label: String, val transient: Boolean) {
    HTTP_NOT_FOUND("The server answered 404 (not found)", false),
    HTTP_FORBIDDEN("The server refused access (401/403)", false),
    HTTP_RATE_LIMITED("The server is rate limiting requests (429)", true),
    HTTP_SERVER_ERROR("The server had an internal error (5xx)", true),
    HTTP_PROXY_AUTH("A proxy asked for authentication (407)", false),
    TIMEOUT("The connection timed out", true),
    CONNECTION_RESET("The connection was interrupted", true),
    CONNECTION_REFUSED("The connection was refused", true),
    UNKNOWN_HOST("The host name could not be resolved", true),
    UNREACHABLE("The network or host is unreachable", true),
    TLS("A secure (TLS/certificate) connection could not be made", false),
}

data class NetworkFinding(
    val kind: NetworkKind,
    val why: String,
    val solution: String,
    /** HTTP 404 means the server was reached and has no such file: that is a dependency problem, not a network one. */
    val category: DiagnosisCategory,
    val status: Int? = null,
)

/** Reads WHAT kind of network failure a message describes. Different kinds need different fixes (retry, credentials, URL). */
object NetworkInterpreter {
    private val STATUS = Regex("(?:[Ss]tatus code|HTTP(?:/\\d(?:\\.\\d)?)?|[Rr]esponse code:?)\\s+(\\d{3})")
    private val HOST = Regex("(?:https?://)([\\w.\\-]+)")
    private val UNKNOWN_HOST = Regex("UnknownHostException|Name or service not known|Temporary failure in name resolution|nodename nor servname")
    private val UNREACHABLE = Regex("Network is unreachable|No route to host")
    private val REFUSED = Regex("Connection refused|ConnectException")
    private val TIMEOUT = Regex("(?i)read timed out|connect timed out|connection timed out|SocketTimeoutException|timeout of \\d+")
    private val RESET = Regex("Connection reset|Software caused connection abort|Premature end of Content-Length|Unexpected end of file from server|Broken pipe|Connection closed|SocketException")
    private val TLS = Regex("SSLHandshakeException|PKIX path building failed|unable to find valid certification path|SSLPeerUnverifiedException|SSLException|certificate")

    fun interpret(message: String): NetworkFinding? {
        val host = HOST.find(message)?.groupValues?.get(1)
        val where = host?.let { " (`$it`)" } ?: ""
        val status = STATUS.find(message)?.groupValues?.get(1)?.toIntOrNull()
        if (status != null) {
            return when {
                status == 404 || status == 410 -> NetworkFinding(
                    NetworkKind.HTTP_NOT_FOUND,
                    "The repository$where was reached but has no file at the requested address. So the connection works; the library, version or path is not on that repository.",
                    "Check that the exact version exists on that repository (open the URL in a browser), correct the group/name/version, or add the repository that really hosts it.",
                    DiagnosisCategory.DEPENDENCY_RESOLUTION, status,
                )
                status == 401 || status == 403 -> NetworkFinding(
                    NetworkKind.HTTP_FORBIDDEN,
                    "The server$where answered $status: it is reachable but refused the request. A private repository needs credentials, and some servers block unknown clients.",
                    "If the repository is private, add its credentials (in CI take them from repository secrets, never write them into the build file). If it should be public, check the URL.",
                    DiagnosisCategory.NETWORK, status,
                )
                status == 407 -> NetworkFinding(
                    NetworkKind.HTTP_PROXY_AUTH,
                    "A proxy between the build machine and the server$where asked for authentication (407).",
                    "Configure the proxy credentials for Gradle (`systemProp.http.proxyUser` / `proxyPassword` in gradle.properties) or build on a machine without that proxy.",
                    DiagnosisCategory.NETWORK, status,
                )
                status == 429 -> NetworkFinding(
                    NetworkKind.HTTP_RATE_LIMITED,
                    "The server$where answered 429: too many requests came from this machine in a short time. Shared CI runners are sometimes limited.",
                    "Wait a few minutes and run the build again. If it keeps happening, cache dependencies in CI or use a mirror.",
                    DiagnosisCategory.NETWORK, status,
                )
                status in 500..599 -> NetworkFinding(
                    NetworkKind.HTTP_SERVER_ERROR,
                    "The server$where answered $status, which means the server itself had a problem. These are usually temporary.",
                    "Run the build again later. If the repository's status page reports an outage, wait for it to end.",
                    DiagnosisCategory.NETWORK, status,
                )
                else -> null
            }
        }
        return when {
            TLS.containsMatchIn(message) -> NetworkFinding(
                NetworkKind.TLS,
                "A secure connection$where could not be established. Possible reasons: the certificate is not trusted by the JDK that runs the build (self-signed or company proxy certificate), the machine's clock is wrong, or the JDK's certificate store is out of date.",
                "Check the date and time on the build machine, use a current JDK, and if a proxy or private server is involved, add its certificate to the JDK trust store. Do not disable certificate checks.",
                DiagnosisCategory.NETWORK,
            )
            UNKNOWN_HOST.containsMatchIn(message) -> NetworkFinding(
                NetworkKind.UNKNOWN_HOST,
                "The build machine could not resolve the server name$where to an address: DNS is failing, there is no internet access, or the host name is misspelled.",
                "If the name is correct, run the build again (DNS failures on CI are often brief). If it repeats, check the repository URL for typos.",
                DiagnosisCategory.NETWORK,
            )
            UNREACHABLE.containsMatchIn(message) -> NetworkFinding(
                NetworkKind.UNREACHABLE,
                "The build machine has no network route to the server$where.",
                "Check that the machine has internet access (and that no firewall blocks the server), then run the build again.",
                DiagnosisCategory.NETWORK,
            )
            TIMEOUT.containsMatchIn(message) -> NetworkFinding(
                NetworkKind.TIMEOUT,
                "The server$where did not answer in time. The server may be slow or overloaded, or the network between the machine and the server is slow or blocked.",
                "Run the build again. If timeouts are frequent, raise Gradle's timeouts (`systemProp.org.gradle.internal.http.connectionTimeout` and `socketTimeout` in gradle.properties).",
                DiagnosisCategory.NETWORK,
            )
            REFUSED.containsMatchIn(message) -> NetworkFinding(
                NetworkKind.CONNECTION_REFUSED,
                "The server$where actively refused the connection: nothing is listening at that address and port, or a firewall rejected it.",
                "Check the address and port in the repository URL, and run the build again in case the server was restarting.",
                DiagnosisCategory.NETWORK,
            )
            RESET.containsMatchIn(message) -> NetworkFinding(
                NetworkKind.CONNECTION_RESET,
                "The connection$where was closed before the download finished. This is typically a temporary network or server problem.",
                "Run the build again. If a specific download keeps failing, delete the partly downloaded file from the Gradle cache and retry.",
                DiagnosisCategory.NETWORK,
            )
            else -> null
        }
    }
}
